/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "_logTitle">NDXLogTitle</param>
/// <returns>NDXLogTitle</returns>
public NDXLogTitle parmLogTitle(NDXLogTitle _logTitle = logTitle)
{
    logTitle = _logTitle;
    return logTitle;
}

/// <summary>
/// PaffH 10.12.21
